-- =============================================
-- SEATS for the new trains
-- Re-runs the exact same set-based generators used in 11_seed_data.sql.
-- They are ON CONFLICT DO NOTHING and keyed off train_master_schema.trains,
-- so re-executing them here simply back-fills seats for the trains added
-- above without touching or duplicating any seat already generated.
-- =============================================

-- SL seats (12 coaches x 72 seats)
INSERT INTO
    train_master_schema.seats (train_number, coach_class, seat_number, berth_type, is_active)
SELECT
    t.train_number, 'SL', 'S' || c.coach_num || '-' || s.seat_num,
    CASE
        WHEN (s.seat_num - 1) % 8 IN (0, 1) THEN 'LOWER'
        WHEN (s.seat_num - 1) % 8 IN (2, 3) THEN 'MIDDLE'
        WHEN (s.seat_num - 1) % 8 IN (4, 5) THEN 'UPPER'
        WHEN (s.seat_num - 1) % 8 = 6 THEN 'SIDE_LOWER'
        ELSE 'SIDE_UPPER'
    END,
    TRUE
FROM train_master_schema.trains t
    CROSS JOIN generate_series (1, 12) AS c (coach_num)
    CROSS JOIN generate_series (1, 72) AS s (seat_num)
WHERE t.train_type IN ('Rajdhani','Shatabdi','Duronto','Superfast','Mail','Express','Sampark Kranti','Garib Rath')
ON CONFLICT (train_number, coach_class, seat_number) DO NOTHING;

-- 3A seats (8 coaches x 72 seats)
INSERT INTO
    train_master_schema.seats (train_number, coach_class, seat_number, berth_type, is_active)
SELECT
    t.train_number, '3A', 'B' || c.coach_num || '-' || s.seat_num,
    CASE
        WHEN (s.seat_num - 1) % 8 IN (0, 1) THEN 'LOWER'
        WHEN (s.seat_num - 1) % 8 IN (2, 3) THEN 'MIDDLE'
        WHEN (s.seat_num - 1) % 8 IN (4, 5) THEN 'UPPER'
        WHEN (s.seat_num - 1) % 8 = 6 THEN 'SIDE_LOWER'
        ELSE 'SIDE_UPPER'
    END,
    TRUE
FROM train_master_schema.trains t
    CROSS JOIN generate_series (1, 8) AS c (coach_num)
    CROSS JOIN generate_series (1, 72) AS s (seat_num)
WHERE t.train_type IN ('Rajdhani','Duronto','Superfast','Mail','Express','Sampark Kranti','Garib Rath')
ON CONFLICT (train_number, coach_class, seat_number) DO NOTHING;

-- 2A seats (4 coaches x 54 seats)
INSERT INTO
    train_master_schema.seats (train_number, coach_class, seat_number, berth_type, is_active)
SELECT
    t.train_number, '2A', 'A' || c.coach_num || '-' || s.seat_num,
    CASE
        WHEN (s.seat_num - 1) % 6 IN (0, 1) THEN 'LOWER'
        WHEN (s.seat_num - 1) % 6 IN (2, 3) THEN 'UPPER'
        WHEN (s.seat_num - 1) % 6 = 4 THEN 'SIDE_LOWER'
        ELSE 'SIDE_UPPER'
    END,
    TRUE
FROM train_master_schema.trains t
    CROSS JOIN generate_series (1, 4) AS c (coach_num)
    CROSS JOIN generate_series (1, 54) AS s (seat_num)
WHERE t.train_type IN ('Rajdhani', 'Duronto')
ON CONFLICT (train_number, coach_class, seat_number) DO NOTHING;

-- 1A seats (2 coaches x 24 seats)
INSERT INTO
    train_master_schema.seats (train_number, coach_class, seat_number, berth_type, is_active)
SELECT
    t.train_number, '1A', 'H' || c.coach_num || '-' || s.seat_num,
    CASE WHEN (s.seat_num - 1) % 4 IN (0, 1) THEN 'LOWER' ELSE 'UPPER' END,
    TRUE
FROM train_master_schema.trains t
    CROSS JOIN generate_series (1, 2) AS c (coach_num)
    CROSS JOIN generate_series (1, 24) AS s (seat_num)
WHERE t.train_type IN ('Rajdhani')
ON CONFLICT (train_number, coach_class, seat_number) DO NOTHING;

-- CC seats (8 coaches x 78 seats)
INSERT INTO
    train_master_schema.seats (train_number, coach_class, seat_number, berth_type, is_active)
SELECT
    t.train_number, 'CC', 'C' || c.coach_num || '-' || s.seat_num,
    CASE
        WHEN (s.seat_num - 1) % 3 = 0 THEN 'WINDOW'
        WHEN (s.seat_num - 1) % 3 = 1 THEN 'AISLE'
        ELSE 'AISLE'
    END,
    TRUE
FROM train_master_schema.trains t
    CROSS JOIN generate_series (1, 8) AS c (coach_num)
    CROSS JOIN generate_series (1, 78) AS s (seat_num)
WHERE t.train_type IN ('Shatabdi', 'Vande Bharat')
ON CONFLICT (train_number, coach_class, seat_number) DO NOTHING;

-- EC seats (2 coaches x 56 seats)
INSERT INTO
    train_master_schema.seats (train_number, coach_class, seat_number, berth_type, is_active)
SELECT
    t.train_number, 'EC', 'E' || c.coach_num || '-' || s.seat_num,
    CASE WHEN (s.seat_num - 1) % 2 = 0 THEN 'WINDOW' ELSE 'AISLE' END,
    TRUE
FROM train_master_schema.trains t
    CROSS JOIN generate_series (1, 2) AS c (coach_num)
    CROSS JOIN generate_series (1, 56) AS s (seat_num)
WHERE t.train_type IN ('Vande Bharat')
ON CONFLICT (train_number, coach_class, seat_number) DO NOTHING;

-- 2S seats (4 coaches x 108 seats)
INSERT INTO
    train_master_schema.seats (train_number, coach_class, seat_number, berth_type, is_active)
SELECT
    t.train_number, '2S', 'D' || c.coach_num || '-' || s.seat_num,
    CASE WHEN (s.seat_num - 1) % 2 = 0 THEN 'WINDOW' ELSE 'AISLE' END,
    TRUE
FROM train_master_schema.trains t
    CROSS JOIN generate_series (1, 4) AS c (coach_num)
    CROSS JOIN generate_series (1, 108) AS s (seat_num)
WHERE t.train_type IN ('Shatabdi','Vande Bharat','Superfast','Mail','Express')
ON CONFLICT (train_number, coach_class, seat_number) DO NOTHING;

